import User from './user.model';

// Method 1: Model.create() — simplest approach
const newUser = await User.create({
  firstName: 'Shivam',
  lastName:  'Kumar',
  email:     'shivam@example.com',
  age:       24,
  isActive:  true
});
// runs schema validation + pre/post save hooks

// Method 2: new Model + save() — useful when you need
// to modify the doc before saving
const user = new User({
  firstName: 'Priya',
  email:     'priya@example.com'
});
user.firstName = user.firstName.toUpperCase();
await user.save();

// Method 3: insertMany — bulk insert
await User.insertMany([
  { firstName: 'Raj',  email: 'raj@example.com'  },
  { firstName: 'Arun', email: 'arun@example.com' }
]);

// Response shape from create()
// {
//   _id:       '66abc123...',
//   firstName: 'Shivam',
//   email:     'shivam@example.com',
//   isActive:  true,
//   createdAt: '2025-06-19T10:00:00.000Z',
//   updatedAt: '2025-06-19T10:00:00.000Z',
//   __v: 0
// }

import User from './user.model';

// Get ALL documents
const allUsers = await User.find();

// Filter by field
const activeUsers = await User.find({ isActive: true });

// Comparison operators
const adults  = await User.find({ age: { $gte: 18 } });
const seniors = await User.find({ age: { $gt: 60 } });
const young   = await User.find({ age: { $lt: 30 } });

// findOne — returns first matching document or null
const user = await User.findOne({ email: 'shivam@example.com' });

// findById — lookup by _id field
const byId = await User.findById('66abc123...');

// Projection — select specific fields only
const names = await User
  .find()
  .select('firstName email -_id');  // include name,email exclude _id

// Exclude sensitive fields
const safe = await User
  .find()
  .select('-password -__v');

// Sort + Pagination
const page  = 2;
const limit = 10;
const paged = await User
  .find({ isActive: true })
  .sort({ createdAt: -1 })       // newest first
  .skip((page - 1) * limit)      // skip page 1
  .limit(limit);                 // take 10

// Count total (for pagination meta)
const total = await User.countDocuments({ isActive: true });

// Multiple filters with AND logic
const result = await User.find({
  isActive: true,
  age: { $gte: 18, $lte: 60 }
});

// OR logic
const orResult = await User.find({
  $or: [
    { firstName: 'Shivam' },
    { email: 'admin@example.com' }
  ]
});

import User from './user.model';

// updateOne — update first matching document
// Returns: { matchedCount, modifiedCount } — NOT the document
await User.updateOne(
  { email: 'shivam@example.com' },      // filter
  { $set: { firstName: 'Shivam V2' } }  // update only this field
);

// updateMany — update all matching documents
await User.updateMany(
  { isActive: false },
  { $set: { isActive: true } }
);

// findByIdAndUpdate — returns the document
// { new: true }          → return UPDATED doc (not old)
// { runValidators: true } → run schema validation on update
const updated = await User.findByIdAndUpdate(
  '66abc123...',
  { $set: { age: 25 } },
  { new: true, runValidators: true }
);

// findOneAndUpdate — by custom filter
const result = await User.findOneAndUpdate(
  { email: 'priya@example.com' },
  { $set: { lastName: 'Sharma' } },
  { new: true }
);

// $inc — increment a numeric field
await User.updateOne(
  { _id: '66abc123...' },
  { $inc: { age: 1 } }       // age = age + 1
);

// $push — add item to array field
await User.updateOne(
  { _id: '66abc123...' },
  { $push: { tags: 'nodejs' } }
);

// $pull — remove item from array field
await User.updateOne(
  { _id: '66abc123...' },
  { $pull: { tags: 'nodejs' } }
);

// upsert — create if not found, update if found
await User.updateOne(
  { email: 'new@example.com' },
  { $set: { firstName: 'New User', isActive: true } },
  { upsert: true }
);

import User from './user.model';

// deleteOne — delete first matching document
// Returns: { deletedCount: 1 } — NOT the document
await User.deleteOne({ email: 'shivam@example.com' });

// findByIdAndDelete — delete by _id, returns the deleted doc
const deleted = await User.findByIdAndDelete('66abc123...');
if (!deleted) throw new Error('User not found');
// 'deleted' contains the document that was removed

// deleteMany — delete all matching documents
await User.deleteMany({ isActive: false });

// WARNING: empty filter deletes EVERYTHING
// await User.deleteMany({});  // NEVER do this in production

// Soft Delete Pattern — RECOMMENDED for production
// Instead of deleting, mark the document as deleted
const softDeleted = await User.findByIdAndUpdate(
  '66abc123...',
  {
    $set: {
      isDeleted:  true,
      deletedAt:  new Date()
    }
  },
  { new: true }
);

// Then filter soft-deleted docs out of all queries:
const activeUsers = await User.find({
  isDeleted: { $ne: true }  // $ne = not equal
});

import User from './user.model';

// CREATE
export const createUser = async (data: any) => {
  const exists = await User.findOne({ email: data.email });
  if (exists) {
    const err: any = new Error('Email already registered');
    err.statusCode  = 409;
    throw err;
  }
  return User.create(data);
};

// READ ALL — paginated
export const getAllUsers = async (page = 1, limit = 10) => {
  const skip  = (page - 1) * limit;
  const total = await User.countDocuments();
  const users = await User
    .find()
    .select('-password')
    .sort({ createdAt: -1 })
    .skip(skip)
    .limit(limit);
  return { users, total, page, pages: Math.ceil(total / limit) };
};

// READ ONE
export const getUserById = async (id: string) => {
  const user = await User.findById(id).select('-password');
  if (!user) {
    const err: any = new Error('User not found');
    err.statusCode  = 404;
    throw err;
  }
  return user;
};

// UPDATE
export const updateUser = async (id: string, data: any) => {
  const user = await User.findByIdAndUpdate(
    id,
    { $set: data },
    { new: true, runValidators: true }
  ).select('-password');
  if (!user) {
    const err: any = new Error('User not found');
    err.statusCode  = 404;
    throw err;
  }
  return user;
};

// DELETE
export const deleteUser = async (id: string) => {
  const user = await User.findByIdAndDelete(id);
  if (!user) {
    const err: any = new Error('User not found');
    err.statusCode  = 404;
    throw err;
  }
};
